const isMain = main.includes(key);
const own = isMain
? `<div class="stat-info-main">Основная характеристика ${mage ? 'мага' : 'воина'}: редкость вещей добавляет именно её.</div>`
: `<div class="stat-info-side">Для ${mage ? 'мага' : 'воина'} второстепенная.</div>`;
