if (__elderAutoShown) return;
if (!state.player.classId) return;
if (state.player.currentLocation !== 'town') return;
const progress = getQuestProgress('firstSteps');
if (progress && progress.stage === 'done') {
__elderAutoShown = true;
return;
}
