function ascendItem(item) {
const target = getAscendTarget(item);
if (!target) return;
const rarity = item.rarity;
const price = getAscendPrice(item);
const pay = getAlchemyPay(item);
const have = pay.have();
if (have < price) {
showToast('⚠', `Мало: ${pay.name.toLowerCase()} ${have} / ${price}`);
return;
}
const refineSuffix = (item.refineLevel > 0) ? ` +${item.refineLevel}` : '';
const extra = getAscendExtraPoints(item);
const ok = confirm(
`Возвысить «${item.name}${refineSuffix}»?\n\n` +
`${RARITIES[rarity].name} → ${RARITIES[target].name}\n` +
`Стоимость: ${pay.fmt(price)}.\n` +
`Бонусы сохранятся, добавится +${extra} к случайным статам.`
);
if (!ok) return;
if (!pay.spend(price)) {
showToast('⚠', pay.gem ? 'Не удалось списать камни' : 'Не удалось списать пыль');
return;
}
const add = rollRarityStats(extra, getRarityStatProfile(item));
const bonus = { ...(item.bonusStats || {}) };
Object.keys(add).forEach(stat => { bonus[stat] = (bonus[stat] || 0) + add[stat]; });
item.rarity = target;
item.bonusStats = bonus;
alchemistDeed('alchemy.ascend');
recalcStats();
const name = `${item.name}${refineSuffix}`;
logLoot(`⬆ Возвышение: ${name} → ${RARITIES[target].name} (${formatBonusStatsShort(add)}; −${pay.fmt(price)})`, 'log-craft rarity-' + target);
showToast('⬆', `${name}: ${RARITIES[target].name}!`);
renderInventory();
updateInventoryFooter();
if (typeof renderEquipSlots === 'function') renderEquipSlots();
updateCharacterPanel();
updateTopStatus();
renderAlchemistAscend();
saveCurrentSlot();
}
function addDustToInventory(colorId, amount) {
if (!amount || amount <= 0) return;
const p = state.player;
const dust = ALCHEMY_DUST[colorId];
if (!dust) return;
let left = amount;
for (const s of p.inventory) {
if (left <= 0) break;
if (s.name !== dust.name) continue;
const add = Math.min(left, ALCHEMY_DUST_STACK_MAX - (s.qty || 0));
if (add > 0) { s.qty = (s.qty || 0) + add; left -= add; }
}
const iconSvg = SVG[dust.icon] || '';
while (left > 0 && p.inventory.length < invMaxSlots()) {
const qty = Math.min(ALCHEMY_DUST_STACK_MAX, left);
p.inventory.push({
id: 'item_' + Date.now() + '_' + Math.random(),
name: dust.name,
type: 'material',
icon: iconSvg,
qty,
sellPrice: 0,
rarity: dust.rarity,
isDust: true,
dustV: DUST_SCALE_VERSION,
});
left -= qty;
}
if (left > 0) showToast('📦', 'Инвентарь переполнен — пыль потеряна');
}
function getDustRoom(colorId, extraSlots) {
const dust = ALCHEMY_DUST[colorId];
if (!dust) return 0;
const p = state.player;
const inStacks = p.inventory.filter(i => i.name === dust.name)
.reduce((sum, i) => sum + Math.max(0, ALCHEMY_DUST_STACK_MAX - (i.qty || 0)), 0);
const freeSlots = Math.max(0, invMaxSlots() - p.inventory.length + (extraSlots || 0));
return inStacks + freeSlots * ALCHEMY_DUST_STACK_MAX;
}
