const rest = alive.filter(m => !marked.includes(m));
const targets = [...marked, ...rest].slice(0, rune.targets);
alive.forEach(m => { if (getDebuff('monster', 'rune', m.index)) removeDebuff('monster', 'rune', m.index); });
