box.classList.toggle('bxm-waiting', waiting);
const p = state.player;
const slots = (p.skillSlots || []).filter(id => id && SKILLS[id] && SKILLS[id].type === 'active' && !SKILLS[id].semiPassive && p.learnedSkills[id]);
